diff --git a/s2/encode.go b/s2/encode.go
index e396cb4..7c54373 100644
--- a/s2/encode.go
+++ b/s2/encode.go
@@ -17,8 +17,11 @@ package s2
 import (
 	"bufio"
 	"encoding/binary"
+	"fmt"
 	"io"
 	"math"
+
+	"github.com/golang/geo/r3"
 )

 const (
@@ -120,6 +123,12 @@ func (e *encoder) writeFloat64(x float64) {
 	e.err = binary.Write(e.w, binary.LittleEndian, x)
 }

+func (e *encoder) writePoint(p Point) {
+	e.writeFloat64(p.X)
+	e.writeFloat64(p.Y)
+	e.writeFloat64(p.Z)
+}
+
 type byteReader interface {
 	io.Reader
 	io.ByteReader
@@ -152,6 +161,9 @@ func (d *decoder) readBool() (x bool) {
 	}
 	var val int8
 	d.err = binary.Read(d.r, binary.LittleEndian, &val)
+	if d.err == nil && val != 0 && val != 1 {
+		d.err = fmt.Errorf("invalid bool value: %d", val)
+	}
 	return val == 1
 }

@@ -203,3 +215,22 @@ func (d *decoder) readUvarint() (x uint64) {
 	x, d.err = binary.ReadUvarint(d.r)
 	return
 }
+
+func isFiniteFloat64(x float64) bool {
+	return !math.IsNaN(x) && !math.IsInf(x, 0)
+}
+
+func isFinitePoint(p Point) bool {
+	return isFiniteFloat64(p.X) && isFiniteFloat64(p.Y) && isFiniteFloat64(p.Z)
+}
+
+func (d *decoder) readPoint() Point {
+	x := d.readFloat64()
+	y := d.readFloat64()
+	z := d.readFloat64()
+	p := Point{r3.Vector{X: x, Y: y, Z: z}}
+	if d.err == nil && !isFinitePoint(p) {
+		d.err = fmt.Errorf("invalid non-finite point: %v", p)
+	}
+	return p
+}
