+		rawID := d.readUvarint()
+		if d.err != nil {
+			return d.err
+		}
+		if rawID >= nextID {
+			return fmt.Errorf("s2: shape ID %d >= nextID %d", rawID, nextID)
+		}
+		id := int32(rawID)
+		if id <= prevShapeID {
+			return fmt.Errorf("s2: shape IDs not strictly increasing (%d <= %d)", id, prevShapeID)
+		}
+		prevShapeID = id
+
+		shape := decodeShape(d)
+		if d.err != nil {
+			return d.err
+		}
+		if shape == nil {
+			return errors.New("s2: decoded nil shape")
+		}
+		shapes[id] = shape
+	}
